<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Profile\Domain\ActiveSession;
use Civi\Lughauth\Features\OAuth\Profile\Domain\MfaSetup;
use Civi\Lughauth\Features\OAuth\Profile\Domain\OidcProfile;
use Civi\Lughauth\Features\OAuth\Profile\Domain\OidcProfileData;

final class ProfileDomainUnitTest extends TestCase
{
    // --- ActiveSession ---

    public function test_active_session_stores_all_fields(): void
    {
        $s = new ActiveSession(
            sessionId: 'sess-1',
            clientId: 'client-a',
            clientName: 'My App',
            ipAddress: '192.168.1.1',
            userAgent: 'Mozilla/5.0',
            lastUsedAt: '2026-05-01T12:00:00+00:00',
            expiration: '2026-05-02T12:00:00+00:00',
        );

        $this->assertSame('sess-1', $s->sessionId);
        $this->assertSame('client-a', $s->clientId);
        $this->assertSame('My App', $s->clientName);
        $this->assertSame('192.168.1.1', $s->ipAddress);
        $this->assertSame('Mozilla/5.0', $s->userAgent);
        $this->assertSame('2026-05-01T12:00:00+00:00', $s->lastUsedAt);
        $this->assertSame('2026-05-02T12:00:00+00:00', $s->expiration);
    }

    public function test_active_session_nullable_fields(): void
    {
        $s = new ActiveSession('sess', 'client', null, null, null, null, 'exp');

        $this->assertNull($s->clientName);
        $this->assertNull($s->ipAddress);
        $this->assertNull($s->userAgent);
        $this->assertNull($s->lastUsedAt);
    }

    // --- MfaSetup ---

    public function test_mfa_setup_stores_seed(): void
    {
        $setup = new MfaSetup('my-seed');
        $this->assertSame('my-seed', $setup->seed);
        $this->assertNull($setup->qrImage);
    }

    public function test_mfa_setup_stores_qr_image(): void
    {
        $setup = new MfaSetup('seed', 'base64encodedimage==');
        $this->assertSame('seed', $setup->seed);
        $this->assertSame('base64encodedimage==', $setup->qrImage);
    }

    // --- OidcProfile ---

    public function test_oidc_profile_stores_all_fields(): void
    {
        $p = new OidcProfile(
            uid: 'prof-uid',
            userUid: 'user-uid',
            givenName: 'Alice',
            familyName: 'Smith',
            middleName: null,
            nickname: 'ali',
            preferredUsername: 'alice_s',
            pictureUrl: 'https://cdn/pic.jpg',
            websiteUrl: null,
            gender: 'female',
            birthdate: '1990-01-15',
            zoneinfo: 'Europe/Madrid',
            locale: 'es',
            phoneNumber: '+34600000000',
            phoneNumberVerified: true,
            addressJson: null,
            updatedAt: '2026-05-01',
            version: 5,
        );

        $this->assertSame('prof-uid', $p->uid);
        $this->assertSame('user-uid', $p->userUid);
        $this->assertSame('Alice', $p->givenName);
        $this->assertSame('Smith', $p->familyName);
        $this->assertSame('ali', $p->nickname);
        $this->assertSame('alice_s', $p->preferredUsername);
        $this->assertTrue($p->phoneNumberVerified);
        $this->assertSame(5, $p->version);
        $this->assertNull($p->middleName);
        $this->assertNull($p->websiteUrl);
    }

    // --- OidcProfileData ---

    public function test_oidc_profile_data_all_nullable_defaults(): void
    {
        $d = new OidcProfileData();

        $this->assertNull($d->givenName);
        $this->assertNull($d->familyName);
        $this->assertNull($d->middleName);
        $this->assertNull($d->nickname);
        $this->assertNull($d->preferredUsername);
        $this->assertNull($d->pictureUrl);
        $this->assertNull($d->websiteUrl);
        $this->assertNull($d->gender);
        $this->assertNull($d->birthdate);
        $this->assertNull($d->zoneinfo);
        $this->assertNull($d->locale);
        $this->assertNull($d->phoneNumber);
        $this->assertNull($d->phoneNumberVerified);
        $this->assertNull($d->addressJson);
    }

    public function test_oidc_profile_data_stores_provided_values(): void
    {
        $d = new OidcProfileData(givenName: 'Bob', familyName: 'Jones', locale: 'en', phoneNumberVerified: false);

        $this->assertSame('Bob', $d->givenName);
        $this->assertSame('Jones', $d->familyName);
        $this->assertSame('en', $d->locale);
        $this->assertFalse($d->phoneNumberVerified);
    }
}
